import numpy as np


class ExplorativeElitePortfolioPolish:
    """
    Restart-based mixed-integer constrained search with Deb's feasibility rules.
    Refinements relative to ExplorativeElitePortfolio (which stalled after ~5% of the budget):
      * a 5th restart mode ("polish") restarts from the incumbent with a small, log-uniform
        step size in [1e-4, 1e-2] (relative to the span) and a short stagnation window, so
        the budget is converted into precision on the continuous variables;
      * polish runs use a smaller population and their own step-size re-inflation range;
      * the step collapse threshold is lower, so refinement is not cut off early;
      * the global exploration modes (archive, incumbent-centred, LHS, IPOP growth) are kept,
        and the LHS mode is still forced after repeated failures.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        d = self.dim
        lb = np.asarray(func.bounds.lb, dtype=float).copy()
        ub = np.asarray(func.bounds.ub, dtype=float).copy()
        types = np.array([str(t) for t in func.variable_types])

        cont = types == "continuous"
        disc = ~cont
        cont_idx = np.where(cont)[0]
        disc_idx = np.where(disc)[0]
        ordi = types == "ordinal"
        binary = types == "binary"
        categ = types == "categorical"

        nv = np.ones(d, dtype=int)
        for i in disc_idx:
            nv[i] = max(1, int(func.n_values[i]))
        span = ub - lb

        self.n_eval = 0
        seen = set()
        gbest = {"f": np.inf, "x": None, "key": (1, np.inf)}
        elite_archive = []
        archive_keys = set()

        def clean(x):
            x = np.clip(x, lb, ub)
            if disc_idx.size:
                x[disc_idx] = np.clip(np.round(x[disc_idx]), 0, nv[disc_idx] - 1)
            return x

        def evaluate(x):
            x = clean(np.asarray(x, dtype=float).copy())
            seen.add(x.tobytes())
            f, g = func(x.copy())
            self.n_eval += 1
            g = np.nan_to_num(np.asarray(g, dtype=float).ravel(), nan=1e6, posinf=1e6, neginf=0.0)
            v = float(np.sum(np.maximum(g, 0.0)))
            f = float(f)
            feas = (v <= 0.0) and np.isfinite(f)
            if feas:
                key = (0, f)
            else:
                if v <= 0.0:
                    v = 1.0
                f = np.inf
                key = (1, v)
            rec = {"x": x, "f": f, "v": v, "key": key, "feas": feas}
            if feas and f < gbest["f"]:
                gbest.update(f=f, x=x.copy(), key=key)
            return rec

        def random_point():
            x = np.empty(d)
            x[cont_idx] = np.random.uniform(lb[cont_idx], ub[cont_idx])
            if disc_idx.size:
                u = np.random.uniform(size=disc_idx.size)
                x[disc_idx] = np.minimum(np.floor(u * nv[disc_idx]), nv[disc_idx] - 1)
            return x

        def lhs_points(n):
            pts = np.empty((n, d))
            for j in range(d):
                pts[:, j] = (np.random.permutation(n) + np.random.uniform(size=n)) / n
            X = np.empty((n, d))
            X[:, cont_idx] = lb[cont_idx] + pts[:, cont_idx] * span[cont_idx]
            if disc_idx.size:
                X[:, disc_idx] = np.minimum(np.floor(pts[:, disc_idx] * nv[disc_idx]), nv[disc_idx] - 1)
            return X

        def disc_step(child, i, pool):
            if binary[i]:
                child[i] = 1.0 - child[i]
            elif ordi[i]:
                if np.random.rand() < 0.8:
                    k = 1 if np.random.rand() < 0.7 else np.random.randint(2, 4)
                    child[i] = child[i] + k * (1 if np.random.rand() < 0.5 else -1)
                else:
                    child[i] = np.random.randint(nv[i])
            elif categ[i]:
                cur = int(round(child[i]))
                new = None
                if np.random.rand() < 0.5 and pool:
                    cand = int(round(pool[np.random.randint(len(pool))]["x"][i]))
                    if cand != cur:
                        new = cand
                if new is None:
                    if nv[i] > 1:
                        r = np.random.randint(nv[i] - 1)
                        new = r + 1 if r >= cur else r
                    else:
                        new = cur
                child[i] = new
            else:
                child[i] = np.random.randint(nv[i])

        def de_child(base, pool):
            F = np.random.uniform(0.4, 0.9)
            n = len(pool)
            r1 = pool[np.random.randint(n)]["x"]
            r2 = pool[np.random.randint(n)]["x"]
            x = base.copy()
            jr = np.random.randint(d)
            for i in range(d):
                if cont[i]:
                    if np.random.rand() < 0.9 or i == jr:
                        x[i] = base[i] + F * (r1[i] - r2[i])
                elif np.random.rand() < 0.3:
                    x[i] = r1[i]
            return clean(x)

        def crossover(p1, p2):
            mask = np.random.rand(d) < 0.5
            c = np.where(mask, p1, p2).astype(float)
            if cont_idx.size:
                a = np.random.uniform(-0.25, 1.25, size=cont_idx.size)
                c[cont_idx] = a * p1[cont_idx] + (1 - a) * p2[cont_idx]
            return clean(c)

        def local_child(parent, s, dvec, pool):
            if dvec is not None and np.random.rand() < 0.25:
                return clean(parent + np.random.uniform(1.0, 2.0) * dvec)
            child = parent.copy()
            ncont = cont_idx.size
            if ncont:
                pm = [1.0, 0.6, 0.3][np.random.randint(3)]
                mask = np.random.rand(ncont) < pm
                if not mask.any():
                    mask[np.random.randint(ncont)] = True
                for k in np.where(mask)[0]:
                    i = cont_idx[k]
                    if np.random.rand() < 0.08:
                        step = np.random.standard_cauchy() * 0.1 * span[i] * min(1.0, 10 * s)
                    else:
                        step = np.random.randn() * s * span[i]
                    child[i] += step
            if disc_idx.size:
                pd = max(1.0 / disc_idx.size, 1.0 / d)
                for i in disc_idx:
                    if np.random.rand() < pd:
                        disc_step(child, i, pool[:10])
            return clean(child)

        def insert(pool, rec, cap=100):
            pool.append(rec)
            pool.sort(key=lambda r: r["key"])
            if len(pool) > cap:
                del pool[cap:]

        def archive_add(recs, cap=40):
            for r in recs:
                k = r["x"].tobytes()
                if k in archive_keys:
                    continue
                archive_keys.add(k)
                elite_archive.append(r)
            elite_archive.sort(key=lambda r: r["key"])
            if len(elite_archive) > cap:
                keep = elite_archive[:cap - 1]
                rest = elite_archive[cap - 1:]
                far = max(rest, key=lambda r: min(
                    np.sum((r["x"] - e["x"]) ** 2) for e in keep)) if rest else None
                if far is not None:
                    keep.append(far)
                elite_archive[:] = keep
                archive_keys.clear()
                archive_keys.update(e["x"].tobytes() for e in elite_archive)

        restart_id = 0
        fail_streak = 0
        pop_mult = 1
        while self.n_eval < self.budget:
            remaining = self.budget - self.n_eval
            base_pop = max(4 * d, 16)

            # 5-mode rotation; LHS forced on odd restarts after repeated failures
            mode = restart_id % 5
            if fail_streak >= 3 and restart_id % 2 == 1:
                mode = 3
            if mode == 4 and gbest["x"] is None:
                mode = 3

            if mode == 4:
                n_pop = int(min(max(4 * d, 12), max(4, remaining // 3)))
            else:
                n_pop = int(min(base_pop * pop_mult, max(4, remaining // 3)))

            pts = lhs_points(n_pop)
            best_before = gbest["key"]

            if restart_id > 0 and mode != 3 and n_pop >= 4:
                k = n_pop // 3
                if mode == 4:
                    sig = float(np.exp(np.random.uniform(np.log(1e-4), np.log(1e-2))))
                else:
                    sig = float(np.exp(np.random.uniform(np.log(0.01), np.log(0.25))))
                if mode in (0, 4) and gbest["x"] is not None:
                    centers = [gbest["x"]]
                elif mode == 1 and elite_archive:
                    centers = [e["x"] for e in elite_archive[:8]]
                elif mode == 2 and len(elite_archive) >= 2:
                    centers = None
                else:
                    centers = [gbest["x"]] if gbest["x"] is not None else []
                if mode == 2 and centers is None:
                    top = elite_archive[:min(10, len(elite_archive))]
                    for j in range(k):
                        a, b = np.random.choice(len(top), 2, replace=False)
                        y = crossover(top[a]["x"], top[b]["x"])
                        y[cont_idx] += np.random.randn(cont_idx.size) * sig * 0.5 * span[cont_idx]
                        for i in disc_idx:
                            if np.random.rand() < 0.05:
                                y[i] = np.random.randint(nv[i])
                        pts[j] = clean(y)
                elif centers:
                    for j in range(k):
                        gx = centers[np.random.randint(len(centers))]
                        y = gx.copy()
                        mask = np.random.rand(cont_idx.size) < (0.5 if mode != 4 else 1.0)
                        ci = cont_idx[mask]
                        y[ci] += np.random.randn(ci.size) * sig * span[ci]
                        dp = 0.1 if mode != 4 else 0.02
                        for i in disc_idx:
                            if np.random.rand() < dp:
                                y[i] = np.random.randint(nv[i])
                        pts[j] = clean(y)

            pool = []
            for x in pts:
                if self.n_eval >= self.budget:
                    break
                insert(pool, evaluate(x), cap=10 ** 9)
            if not pool:
                break
            pool.sort(key=lambda r: r["key"])
            pool = pool[:100]

            inc = pool[0]
            if mode == 4:
                s = float(np.exp(np.random.uniform(np.log(1e-4), np.log(1e-2))))
                stag_limit = max(100, 15 * d) + 10 * n_pop + self.budget // 30
            else:
                s = float(np.exp(np.random.uniform(np.log(0.05), np.log(0.3))))
                stag_limit = max(200, 30 * d) + 20 * n_pop + self.budget // 15
            dvec = None
            last = self.n_eval
            collapses = 0

            while self.n_eval < self.budget:
                if self.n_eval - last > stag_limit:
                    break
                if s < 1e-7:
                    # re-inflate instead of stopping
                    collapses += 1
                    if collapses % 2 == 1:
                        s = float(np.exp(np.random.uniform(np.log(1e-2), np.log(0.5))))
                    else:
                        s = float(np.exp(np.random.uniform(np.log(1e-4), np.log(1e-2))))
                    dvec = None
                    last = self.n_eval
                base = inc["x"]
                base_key = inc["key"]
                N = len(pool)
                u = np.random.rand()
                op = "loc"

                if u < 0.03:
                    op = "probe"
                    x = random_point()
                elif u < 0.36:
                    op = "de"
                    x = de_child(base, pool)
                elif u < 0.86:
                    x = local_child(base, s, dvec, pool)
                elif u < 0.94 and N >= 2:
                    op = "cross"
                    p1 = pool[np.random.randint(N)]["x"]
                    p2 = pool[np.random.randint(N)]["x"]
                    x = crossover(base, p2 if np.random.rand() < 0.5 else p1)
                else:
                    op = "exp"
                    par = pool[min(np.random.randint(N), np.random.randint(N))]
                    x = local_child(par["x"], min(0.5, 2 * s), None, pool)

                tries = 0
                while x.tobytes() in seen and tries < 10:
                    tries += 1
                    if op == "de":
                        x = de_child(base, pool)
                    elif op == "probe":
                        x = random_point()
                    else:
                        x = local_child(base, s, dvec, pool)
                if x.tobytes() in seen:
                    op = "rand"
                    x = random_point()

                rec = evaluate(x)
                success = rec["key"] < base_key

                if op == "loc":
                    s *= 1.5 if success else 1.5 ** (-0.25)
                    s = float(np.clip(s, 1e-8, 0.5))
                    if success:
                        dv = np.zeros(d)
                        dv[cont_idx] = rec["x"][cont_idx] - base[cont_idx]
                        dvec = dv
                    elif dvec is not None:
                        dvec = dvec * 0.8
                        if np.linalg.norm(dvec) < 1e-10:
                            dvec = None

                if success:
                    inc = rec
                    last = self.n_eval
                insert(pool, rec)

            archive_add(pool[:5])

            # IPOP-style population growth after consecutive failed global restarts;
            # polish restarts do not count toward growth
            if gbest["key"] < best_before:
                fail_streak = 0
                pop_mult = 1
            elif mode != 4:
                fail_streak += 1
                if fail_streak >= 2:
                    pop_mult = min(pop_mult * 2, 8)
            restart_id += 1

        return gbest["f"], gbest["x"]
